// GPU inference for the analysis harness, see iw_gpu.h. Built by
// build.sh --gpu: includes the trainer's tensor substrate and nets, so the
// forward is exactly the trainer's rollout forward. pufferl_algo.cu is
// generated by build.sh from src/pufferl.cu: everything up to and including
// its #include "algo.cu" (which pulls in impulse_wars.cu through
// src/ocean.cu), without the NCCL, NVML and OpenMP headers.
// PRECISION_FLOAT builds it in fp32, otherwise it's bf16 like training.

#include "pufferl_algo.cu"
#include "iw_gpu.h"

#define IW_GPU_CHECK(call)                                                                                             \
    do {                                                                                                               \
        cudaError_t err_ = (call);                                                                                     \
        if (err_ != cudaSuccess) {                                                                                     \
            fprintf(stderr, "iw_gpu: %s failed at %s:%d: %s\n", #call, __FILE__, __LINE__, cudaGetErrorString(err_)); \
            exit(1);                                                                                                   \
        }                                                                                                              \
    } while (0)

// per thread cuBLAS workspace; the forward's GEMMs are small
#define IW_GPU_CUBLAS_WORKSPACE (4 * 1024 * 1024)
// the checkpoint holds each param tensor 8 floats aligned, as the trainer's
// bf16 param buffer it was cast from
#define IW_GPU_PARAM_ALIGN 8

struct iwGpuModel {
    Arch arch;
    Weights weights;
    Allocator params;
    int hidden, layers;
};

struct iwGpuNet {
    iwGpuModel *model;
    int B;
    bool inputs;
    Allocator acts;
    Activations a;
    // (layers, B, hidden) recurrent state
    Prec state;
    // the obs the encoder reads; aliases obsDev in fp32
    Prec obs;
    // pinned host buffers and their device copies
    float *obsHost, *termHost, *logitsHost;
    float *obsDev, *termDev, *logitsDev;
    // encoder inputs, with inputs
    float *concatHost, *ownRecHost, *enemyRecHost, *fwRecHost;
    int *ownActiveHost, *enemyActiveHost, *fwActiveHost;
    float *concatDev, *ownRecDev, *enemyRecDev, *fwRecDev;
    cudaGraphExec_t graph;
};

static int iwDevice = 0;
// every net of a thread runs on its stream, as they share its cuBLAS
// handle and workspace
static thread_local cudaStream_t iwStream = NULL;

static int iw_gpu_atn_sum(void) {
    const int actSizes[] = ACT_SIZES;
    int n = 0;
    for (int i = 0; i < NUM_ATNS; i++) {
        n += actSizes[i];
    }
    return n;
}

static void iw_gpu_thread_init(void) {
    if (iwStream != NULL) {
        return;
    }
    IW_GPU_CHECK(cudaSetDevice(iwDevice));
    IW_GPU_CHECK(cudaStreamCreateWithFlags(&iwStream, cudaStreamNonBlocking));
    // algo.cu's GEMMs use the thread's g_cublas_handle
    if (cublasCreate(&g_cublas_handle) != CUBLAS_STATUS_SUCCESS) {
        fprintf(stderr, "iw_gpu: cublasCreate failed\n");
        exit(1);
    }
    IW_GPU_CHECK(cudaMalloc(&g_cublas_workspace, IW_GPU_CUBLAS_WORKSPACE));
    cublasSetWorkspace(g_cublas_handle, g_cublas_workspace, IW_GPU_CUBLAS_WORKSPACE);
    cublasSetMathMode(g_cublas_handle, CUBLAS_DEFAULT_MATH);
}

__global__ void iw_gpu_zero_term(precision_t *state, const float *terminals, int B, int H, int n) {
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    if (idx >= n) {
        return;
    }
    if (terminals[(idx / H) % B] > 0.5f) {
        state[idx] = from_float(0.0f);
    }
}

__global__ void iw_gpu_to_float(float *dst, const precision_t *src, int n) {
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    if (idx < n) {
        dst[idx] = to_float(src[idx]);
    }
}

static void iw_gpu_copy_out(float *host, float *dev, const precision_t *src, long n, cudaStream_t stream) {
    iw_gpu_to_float<<<grid_size(n), BLOCK_SIZE, 0, stream>>>(dev, src, n);
    IW_GPU_CHECK(cudaMemcpyAsync(host, dev, n * sizeof(float), cudaMemcpyDeviceToHost, stream));
}

// one forward: obs and terminals in, logits (and encoder inputs) out
static void iw_gpu_forward(iwGpuNet *n, cudaStream_t stream) {
    iwGpuModel *m = n->model;
    int B = n->B;
    long obsN = (long)B * OBS_SIZE;
    IW_GPU_CHECK(cudaMemcpyAsync(n->obsDev, n->obsHost, obsN * sizeof(float), cudaMemcpyHostToDevice, stream));
    IW_GPU_CHECK(cudaMemcpyAsync(n->termDev, n->termHost, B * sizeof(float), cudaMemcpyHostToDevice, stream));
    if (USE_BF16) {
        cast<<<grid_size(obsN), BLOCK_SIZE, 0, stream>>>(n->obs.data, n->obsDev, obsN);
    }
    int stateN = m->layers * B * m->hidden;
    iw_gpu_zero_term<<<grid_size(stateN), BLOCK_SIZE, 0, stream>>>(n->state.data, n->termDev, B, m->hidden, stateN);

    Prec dec = arch_forward(&m->arch, m->weights, n->a, n->obs, n->state, stream);
    iw_gpu_copy_out(n->logitsHost, n->logitsDev, dec.data, (long)B * (iw_gpu_atn_sum() + 1), stream);

    if (n->inputs) {
        IwEncoderActivations *ea = (IwEncoderActivations *)n->a.encoder;
        iw_gpu_copy_out(n->concatHost, n->concatDev, ea->concat.data, (long)B * IW_CONCAT, stream);
        iw_gpu_copy_out(n->ownRecHost, n->ownRecDev, ea->own_rec.data, (long)B * IW_NUM_OWN_PROJECTILES * IW_PROJ_FEATURES, stream);
        iw_gpu_copy_out(n->enemyRecHost, n->enemyRecDev, ea->enemy_rec.data, (long)B * IW_NUM_ENEMY_PROJECTILES * IW_PROJ_FEATURES, stream);
        iw_gpu_copy_out(n->fwRecHost, n->fwRecDev, ea->fw_rec.data, (long)B * IW_NUM_FLOATING_WALLS * IW_FW_FEATURES, stream);
        IW_GPU_CHECK(cudaMemcpyAsync(n->ownActiveHost, ea->own_active.data, (long)B * IW_NUM_OWN_PROJECTILES * sizeof(int), cudaMemcpyDeviceToHost, stream));
        IW_GPU_CHECK(cudaMemcpyAsync(n->enemyActiveHost, ea->enemy_active.data, (long)B * IW_NUM_ENEMY_PROJECTILES * sizeof(int), cudaMemcpyDeviceToHost, stream));
        IW_GPU_CHECK(cudaMemcpyAsync(n->fwActiveHost, ea->fw_active.data, (long)B * IW_NUM_FLOATING_WALLS * sizeof(int), cudaMemcpyDeviceToHost, stream));
    }
}

template <typename T>
static T *iw_gpu_host(long n) {
    T *p;
    IW_GPU_CHECK(cudaHostAlloc((void **)&p, n * sizeof(T), cudaHostAllocDefault));
    memset(p, 0, n * sizeof(T));
    return p;
}

static float *iw_gpu_dev(long n) {
    float *p;
    IW_GPU_CHECK(cudaMalloc((void **)&p, n * sizeof(float)));
    return p;
}

extern "C" {

const char *iw_gpu_precision(void) {
    return USE_BF16 ? "bf16" : "fp32";
}

bool iw_gpu_init(int device) {
    int count = 0;
    cudaError_t err = cudaGetDeviceCount(&count);
    if (err != cudaSuccess || count == 0) {
        fprintf(stderr, "iw_gpu: no CUDA device: %s\n", err != cudaSuccess ? cudaGetErrorString(err) : "none found");
        return false;
    }
    if (device < 0 || device >= count) {
        fprintf(stderr, "iw_gpu: no CUDA device %d, there are %d\n", device, count);
        return false;
    }
    iwDevice = device;
    IW_GPU_CHECK(cudaSetDevice(device));
    return true;
}

iwGpuModel *iw_gpu_load(const float *weights, long numFloats, int hidden, int layers) {
    IW_GPU_CHECK(cudaSetDevice(iwDevice));
    iwGpuModel *m = (iwGpuModel *)calloc(1, sizeof(iwGpuModel));
    m->hidden = hidden;
    m->layers = layers;
    m->arch = build_arch(OBS_SIZE, hidden, layers, iw_gpu_atn_sum(), false, 1);
    m->weights = weights_create(&m->arch, &m->params);
    alloc_create(&m->params);

    float *src = iw_gpu_dev(numFloats);
    IW_GPU_CHECK(cudaMemcpy(src, weights, numFloats * sizeof(float), cudaMemcpyHostToDevice));
    long off = 0;
    for (int i = 0; i < m->params.num_regs; i++) {
        AllocEntry *r = &m->params.regs[i];
        assert(r->elem_size == sizeof(precision_t) && "iw_gpu: param is not a precision tensor");
        long n = numel(r->shape);
        off = (off + IW_GPU_PARAM_ALIGN - 1) & ~(long)(IW_GPU_PARAM_ALIGN - 1);
        if (off + n > numFloats) {
            fprintf(stderr, "iw_gpu: checkpoint has %ld floats, hidden %d layers %d needs more\n", numFloats, hidden, layers);
            exit(1);
        }
        cast<<<grid_size(n), BLOCK_SIZE>>>((precision_t *)*r->data_ptr, src + off, (int)n);
        off += n;
    }
    IW_GPU_CHECK(cudaDeviceSynchronize());
    IW_GPU_CHECK(cudaFree(src));
    return m;
}

iwGpuNet *iw_gpu_net(iwGpuModel *model, int batch, bool inputs) {
    iw_gpu_thread_init();
    iwGpuNet *n = (iwGpuNet *)calloc(1, sizeof(iwGpuNet));
    n->model = model;
    n->B = batch;
    n->inputs = inputs;
    int B = batch;
    long obsN = (long)B * OBS_SIZE;
    long logitsN = (long)B * (iw_gpu_atn_sum() + 1);

    n->a = arch_reg_rollout(&model->arch, model->weights, &n->acts, B);
    n->state = {.shape = {model->layers, B, model->hidden}};
    alloc_register(&n->acts, &n->state);
    if (USE_BF16) {
        n->obs = {.shape = {B, OBS_SIZE}};
        alloc_register(&n->acts, &n->obs);
    }
    alloc_create(&n->acts);

    n->obsHost = iw_gpu_host<float>(obsN);
    n->termHost = iw_gpu_host<float>(B);
    n->logitsHost = iw_gpu_host<float>(logitsN);
    n->obsDev = iw_gpu_dev(obsN);
    n->termDev = iw_gpu_dev(B);
    n->logitsDev = iw_gpu_dev(logitsN);
    if (!USE_BF16) {
        n->obs = {.data = (precision_t *)n->obsDev, .shape = {B, OBS_SIZE}};
    }
    if (inputs) {
        long ownN = (long)B * IW_NUM_OWN_PROJECTILES;
        long enemyN = (long)B * IW_NUM_ENEMY_PROJECTILES;
        long fwN = (long)B * IW_NUM_FLOATING_WALLS;
        n->concatHost = iw_gpu_host<float>((long)B * IW_CONCAT);
        n->ownRecHost = iw_gpu_host<float>(ownN * IW_PROJ_FEATURES);
        n->enemyRecHost = iw_gpu_host<float>(enemyN * IW_PROJ_FEATURES);
        n->fwRecHost = iw_gpu_host<float>(fwN * IW_FW_FEATURES);
        n->ownActiveHost = iw_gpu_host<int>(ownN);
        n->enemyActiveHost = iw_gpu_host<int>(enemyN);
        n->fwActiveHost = iw_gpu_host<int>(fwN);
        n->concatDev = iw_gpu_dev((long)B * IW_CONCAT);
        n->ownRecDev = iw_gpu_dev(ownN * IW_PROJ_FEATURES);
        n->enemyRecDev = iw_gpu_dev(enemyN * IW_PROJ_FEATURES);
        n->fwRecDev = iw_gpu_dev(fwN * IW_FW_FEATURES);
    }

    // run once outside the graph so cuBLAS picks and loads its kernels
    // before capture, then start from a zero state
    iw_gpu_forward(n, iwStream);
    IW_GPU_CHECK(cudaMemsetAsync(n->state.data, 0, numel(n->state.shape) * sizeof(precision_t), iwStream));
    IW_GPU_CHECK(cudaStreamSynchronize(iwStream));

    cudaGraph_t graph;
    IW_GPU_CHECK(cudaStreamBeginCapture(iwStream, cudaStreamCaptureModeThreadLocal));
    iw_gpu_forward(n, iwStream);
    IW_GPU_CHECK(cudaStreamEndCapture(iwStream, &graph));
    IW_GPU_CHECK(cudaGraphInstantiate(&n->graph, graph, 0));
    IW_GPU_CHECK(cudaGraphDestroy(graph));
    return n;
}

float *iw_gpu_obs(iwGpuNet *net) {
    return net->obsHost;
}

float *iw_gpu_terminals(iwGpuNet *net) {
    return net->termHost;
}

const float *iw_gpu_logits(iwGpuNet *net) {
    return net->logitsHost;
}

void iw_gpu_launch(iwGpuNet *net) {
    IW_GPU_CHECK(cudaGraphLaunch(net->graph, iwStream));
}

void iw_gpu_wait(void) {
    IW_GPU_CHECK(cudaStreamSynchronize(iwStream));
}

iwGpuInputs iw_gpu_inputs(iwGpuNet *net) {
    assert(net->inputs && "iw_gpu: net wasn't created with inputs");
    iwGpuInputs in = {};
    in.concat = net->concatHost;
    in.ownRec = net->ownRecHost;
    in.ownActive = net->ownActiveHost;
    in.enemyRec = net->enemyRecHost;
    in.enemyActive = net->enemyActiveHost;
    in.fwRec = net->fwRecHost;
    in.fwActive = net->fwActiveHost;
    return in;
}

void iw_gpu_free_net(iwGpuNet *net) {
    IW_GPU_CHECK(cudaStreamSynchronize(iwStream));
    IW_GPU_CHECK(cudaGraphExecDestroy(net->graph));
    IW_GPU_CHECK(cudaFree(net->acts.mem));
    free(net->acts.regs);
    float *dev[] = {net->obsDev, net->termDev, net->logitsDev, net->concatDev, net->ownRecDev, net->enemyRecDev, net->fwRecDev};
    for (size_t i = 0; i < sizeof(dev) / sizeof(dev[0]); i++) {
        if (dev[i] != NULL) {
            IW_GPU_CHECK(cudaFree(dev[i]));
        }
    }
    void *host[] = {net->obsHost, net->termHost, net->logitsHost, net->concatHost, net->ownRecHost, net->enemyRecHost,
                    net->fwRecHost, net->ownActiveHost, net->enemyActiveHost, net->fwActiveHost};
    for (size_t i = 0; i < sizeof(host) / sizeof(host[0]); i++) {
        if (host[i] != NULL) {
            IW_GPU_CHECK(cudaFreeHost(host[i]));
        }
    }
    free(net->a.encoder);
    free(net->a.decoder);
    free(((MinGRUActivations *)net->a.network)->combined);
    free(net->a.network);
    free(net);
}

} // extern "C"
